class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            print("Balance kam hai!")
            return False
        self.balance -= amount
        return True

acc = BankAccount("Ravi", 1000)
acc.deposit(500)
print(acc.balance)  # output: 1500

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

r = Rectangle(5, 3)
print(r.area())       # output: 15
print(r.perimeter())  # output: 16

class Student:
    def __init__(self, name, marks):
        self.name = name
        self.marks = marks

    def average(self):
        return sum(self.marks) / len(self.marks)

    def grade(self):
        avg = self.average()
        if avg >= 90:
            return "A"
        if avg >= 75:
            return "B"
        if avg >= 60:
            return "C"
        return "D"

s = Student("Meena", [85, 90, 88])
print(s.grade())  # output: B

class Circle:
    PI = 3.14159

    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return self.PI * self.radius ** 2

    def circumference(self):
        return 2 * self.PI * self.radius

c = Circle(5)
print(round(c.area(), 2))         # output: 78.54
print(round(c.circumference(), 2))  # output: 31.42

